"""Mathematical equivalence checking between two parsed answers.

The public entry points are :func:`verify` (list-aware, timeout-guarded) and
:func:`sympy_expr_eq` (a single pair of SymPy objects).

Equivalence is decided by a ladder of increasingly expensive strategies, from a
structural identity check through numeric evaluation up to symbolic
simplification, with dedicated handling for the structured objects that show up
in real answers: sets, intervals, tuples, matrices and relations.
"""

from __future__ import annotations

import itertools
from typing import Any, Callable, Iterable, Sequence

import sympy
from sympy import (
    And,
    Basic,
    Eq,
    FiniteSet,
    Float,
    Interval,
    MatrixBase,
    Number,
    Or,
    Set,
    Symbol,
    Tuple,
    Union,
)
from sympy.core.relational import Relational
from sympy.logic.boolalg import BooleanFunction

from math_verify.errors import TimeoutException
from math_verify.utils import timeout

__all__ = ["sympy_expr_eq", "verify"]


# Simplification can wander into pathological territory; every call is wrapped
# so a failure just means "this strategy did not prove equality".
def _safe(fn: Callable[[], Any], default: Any = None) -> Any:
    try:
        return fn()
    except TimeoutException:
        raise
    except Exception:
        return default
    except RecursionError:
        return default


# ---------------------------------------------------------------------------
# Numeric comparison
# ---------------------------------------------------------------------------


def sympy_numeric_eq(
    gold: Any, target: Any, float_rounding: int, numeric_precision: int
) -> bool:
    """Compare two constant expressions numerically.

    Both sides are evaluated to ``numeric_precision`` significant digits and
    then rounded to ``float_rounding`` decimal places.  That two-step is what
    makes 1/3 equal 0.33 at precision 2 but not at precision 6.
    """
    if getattr(gold, "free_symbols", None) or getattr(target, "free_symbols", None):
        return False

    def _evaluate(expr: Any) -> Any:
        value = expr.evalf(numeric_precision) if hasattr(expr, "evalf") else sympy.sympify(expr)
        return value

    gold_value = _safe(lambda: _evaluate(gold))
    target_value = _safe(lambda: _evaluate(target))
    if gold_value is None or target_value is None:
        return False

    # Complex numbers: compare the components separately.
    if _safe(lambda: bool(gold_value.is_real is False or target_value.is_real is False), False):
        as_complex = _safe(lambda: (complex(gold_value), complex(target_value)))
        if as_complex is None:
            return False
        a, b = as_complex
        tolerance = 10 ** (-float_rounding)
        return (
            abs(a.real - b.real) <= tolerance * 1.5
            and abs(a.imag - b.imag) <= tolerance * 1.5
        )

    rounded = _safe(
        lambda: gold_value.round(float_rounding) == target_value.round(float_rounding),
        False,
    )
    if rounded:
        return True

    # Rounding is brittle right on a .5 boundary, so also accept a plain
    # absolute/relative tolerance at the same scale.
    def _tolerant() -> bool:
        a = float(gold_value)
        b = float(target_value)
        tolerance = 10 ** (-float_rounding)
        return abs(a - b) <= tolerance * (1 + min(abs(a), abs(b)))

    return bool(_safe(_tolerant, False))


# ---------------------------------------------------------------------------
# Symbolic comparison
# ---------------------------------------------------------------------------


def sympy_symbolic_eq(gold: Any, target: Any) -> bool:
    """Try to prove ``gold - target == 0`` symbolically."""
    if _safe(lambda: bool(gold == target), False):
        return True

    difference = _safe(lambda: gold - target)
    if difference is None:
        return False

    for transform in (
        sympy.simplify,
        lambda e: sympy.simplify(sympy.expand(e)),
        lambda e: sympy.simplify(sympy.trigsimp(e)),
        lambda e: sympy.cancel(sympy.together(e)),
        lambda e: sympy.radsimp(sympy.simplify(e)),
    ):
        result = _safe(lambda: transform(difference))
        if result is not None and _safe(lambda: bool(result == 0), False):
            return True
    return False


def _expr_eq(
    gold: Any,
    target: Any,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    """Numeric-then-symbolic comparison of two scalar expressions."""
    if _safe(lambda: bool(gold == target), False):
        return True

    gold_symbols = getattr(gold, "free_symbols", set()) or set()
    target_symbols = getattr(target, "free_symbols", set()) or set()

    if not gold_symbols and not target_symbols:
        if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
            return True
        # Exact constants can still need symbolic work, e.g. nested radicals.
        return sympy_symbolic_eq(gold, target)

    # With free symbols on either side, numeric substitution is meaningless;
    # the symbols must line up and the difference must vanish identically.
    if gold_symbols != target_symbols:
        return False
    return sympy_symbolic_eq(gold, target)


# ---------------------------------------------------------------------------
# strict=False: compare up to a renaming of the free symbols
# ---------------------------------------------------------------------------


def _symbols_in_order(expr: Any) -> list[Symbol]:
    """Free symbols in order of first appearance (deterministic)."""
    seen: list[Symbol] = []

    def walk(node: Any) -> None:
        if isinstance(node, MatrixBase):
            for element in node:
                walk(element)
            return
        if isinstance(node, Symbol):
            if node not in seen:
                seen.append(node)
            return
        for arg in getattr(node, "args", ()) or ():
            walk(arg)

    walk(expr)
    return seen


def _rename(expr: Any, mapping: dict) -> Any:
    if isinstance(expr, MatrixBase):
        return expr.applyfunc(lambda e: e.subs(mapping, simultaneous=True))
    return expr.subs(mapping, simultaneous=True)


def _canonical_symbol_forms(expr: Any, limit: int = 6) -> Iterable[Any]:
    """Yield the expression with its free symbols renamed to placeholders.

    The first candidate maps symbols by order of appearance, which handles the
    common case in one shot.  If the two expressions order their symbols
    differently we fall back to trying every bijection, which is affordable
    because answers do not contain many distinct variables.
    """
    symbols = _symbols_in_order(expr)
    if not symbols:
        yield expr
        return

    placeholders = [Symbol(f"_canon{i}", real=True) for i in range(len(symbols))]
    yield _rename(expr, dict(zip(symbols, placeholders)))

    if len(symbols) > 1 and len(symbols) <= limit:
        for permutation in itertools.permutations(range(len(symbols))):
            if list(permutation) == list(range(len(symbols))):
                continue
            mapping = {symbols[i]: placeholders[permutation[i]] for i in range(len(symbols))}
            yield _rename(expr, mapping)


# ---------------------------------------------------------------------------
# Structured objects
# ---------------------------------------------------------------------------


def _elements_of(expr: Any) -> list[Any] | None:
    """Ordered elements of a set-like/tuple-like object, preserving source order."""
    unsorted = getattr(expr, "_unsorted_args", None)
    if unsorted is not None:
        return list(unsorted)
    if isinstance(expr, FiniteSet):
        return list(expr.args)
    if isinstance(expr, (Tuple, tuple, list)):
        return list(expr)
    return None


def _match_unordered(
    gold_items: Sequence[Any], target_items: Sequence[Any], compare: Callable[[Any, Any], bool]
) -> bool:
    """Every gold item pairs with a distinct target item."""
    if len(gold_items) != len(target_items):
        return False
    remaining = list(range(len(target_items)))
    for item in gold_items:
        for index in remaining:
            if compare(item, target_items[index]):
                remaining.remove(index)
                break
        else:
            return False
    return True


def sympy_compare_interval(
    gold: Interval, target: Interval, compare: Callable[[Any, Any], bool]
) -> bool:
    return (
        gold.left_open == target.left_open
        and gold.right_open == target.right_open
        and compare(gold.start, target.start)
        and compare(gold.end, target.end)
    )


def sympy_compare_matrix(
    gold: MatrixBase, target: MatrixBase, compare: Callable[[Any, Any], bool]
) -> bool:
    if gold.shape != target.shape:
        return False
    return all(compare(a, b) for a, b in zip(gold, target))


def _as_set(expr: Any) -> Any:
    """Turn a relational/boolean into the set of values satisfying it."""

    def convert() -> Any:
        symbols = expr.free_symbols
        if len(symbols) != 1:
            return None
        return expr.as_set()

    return _safe(convert)


def sympy_compare_relational(
    gold: Any,
    target: Any,
    float_rounding: int,
    numeric_precision: int,
    compare: Callable[[Any, Any], bool],
) -> bool:
    """Compare two relations, allowing a flipped direction or a scaled equation."""
    if _safe(lambda: bool(gold == target), False):
        return True

    # x >= 5  vs  5 <= x
    reversed_target = _safe(lambda: target.reversed)
    if reversed_target is not None and _safe(lambda: bool(gold == reversed_target), False):
        return True

    if isinstance(gold, Relational) and isinstance(target, Relational):
        same_direction = type(gold) is type(target)
        flipped = reversed_target is not None and type(gold) is type(reversed_target)
        if not (same_direction or flipped):
            return False

        oriented = target if same_direction else reversed_target
        gold_expr = _safe(lambda: gold.lhs - gold.rhs)
        target_expr = _safe(lambda: oriented.lhs - oriented.rhs)
        if gold_expr is None or target_expr is None:
            return False

        if compare(gold_expr, target_expr):
            return True

        # 34x+45y+100 = 0  vs  -34x-45y-100 = 0 differ by a constant factor.
        # For an equation any non-zero factor is fine; for an inequality the
        # factor has to be positive or the direction would flip.
        ratio = _safe(lambda: sympy.simplify(gold_expr / target_expr))
        if ratio is not None and _safe(lambda: bool(ratio.is_number and ratio != 0), False):
            if isinstance(gold, Eq):
                return True
            return bool(_safe(lambda: bool(ratio.is_positive), False))
    return False


# ---------------------------------------------------------------------------
# The main dispatcher
# ---------------------------------------------------------------------------


def sympy_expr_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    """Return whether two SymPy objects represent the same mathematical answer.

    Args:
        gold: the reference answer.
        target: the answer being checked.
        float_rounding: decimal places used when comparing numbers.
        numeric_precision: significant digits used when evaluating.
        allow_set_relation_comp: also compare a relation against a set/interval,
            e.g. ``x > 5`` against ``(5, oo)``.
        strict: when ``False``, expressions that differ only in the names of
            their variables are considered equal.
    """

    def compare(a: Any, b: Any) -> bool:
        return _dispatch(a, b, float_rounding, numeric_precision, allow_set_relation_comp, strict)

    if compare(gold, target):
        return True

    if not strict:
