#: the parser handles best.
COT_FEW_SHOTS: list[dict[str, str]] = [
    {
        "problem": "What is $1+1$?",
        "solution": "Adding one to one gives two.\nThe final answer is $\\boxed{2}$.",
    },
    {
        "problem": "Simplify $\\frac{4}{8}$.",
        "solution": (
            "Both numerator and denominator share a factor of 4, so "
            "$\\frac{4}{8}=\\frac{1}{2}$.\n"
            "The final answer is $\\boxed{\\frac{1}{2}}$."
        ),
    },
    {
        "problem": "Solve $x^2-5x+6=0$.",
        "solution": (
            "Factoring gives $(x-2)(x-3)=0$, so $x=2$ or $x=3$.\n"
            "The final answer is $\\boxed{\\{2,3\\}}$."
        ),
    },
    {
        "problem": "For what values of $x$ is $1\\le x<4$?",
        "solution": (
            "The condition describes every number from 1 up to but not "
            "including 4.\n"
            "The final answer is $\\boxed{[1,4)}$."
        ),
    },
    {
        "problem": "What is 20\\% of 50?",
        "solution": (
            "Twenty percent is $\\frac{1}{5}$, and $\\frac{50}{5}=10$.\n"
            "The final answer is $\\boxed{10}$."
        ),
    },
]

#: Exemplars for models asked to answer with a JSON object.
JSON_FEW_SHOTS: list[dict[str, str]] = [
    {
        "problem": "What is $1+1$?",
        "solution": '{"reasoning": "One plus one is two.", "answer": "2"}',
    },
    {
        "problem": "Simplify $\\frac{4}{8}$.",
        "solution": (
            '{"reasoning": "Divide numerator and denominator by 4.", '
            '"answer": "\\\\frac{1}{2}"}'
        ),
    },
]


def get_few_shots(style: str = "cot") -> list[dict[str, str]]:
    """Return the exemplars for a prompting ``style`` ("cot" or "json")."""
    if style == "cot":
        return list(COT_FEW_SHOTS)
    if style == "json":
        return list(JSON_FEW_SHOTS)
    raise ValueError(f"Unknown few-shot style: {style!r}")
